        "q": "2008 年 5 月 12 日，我国发生了震惊世界的四川汶川大地震。在这次抗震救灾中，全党全军全国人民在党中央国务院领导下众志成城，坚持把抢救人的生命放在第一位，只要有一线希望就尽百倍努力，84017名群众被从废墟中抢救出来，140 万名被困群众得到解救，430 多万名伤病员得到及时救治，其中 1 万多名重伤员被快速转送到全国 20 个省区市 375 家医院。这些事实生动地体现了：",
