        "q": "2008 年 8 月 8 日至 24 日，第 29 届奥林匹克运动会在北京成功举行。中国政府和人民认真履行了对国际社会的郑重承诺。中国提出的奥运理念丰富了奥林匹克精神，彰显了中国和世界在追求人类共同进步中坚守的共同梦想。中国提出的本届奥运会理念是：",
