        "q": "结合材料 回答 问题：材料 1“余维 欧 美之 进化，凡 以三大主义 ：曰 民族、 曰 民权 、曰 民生。 罗 马之亡 ，民 族主 义兴 ，而欧洲各国以 独立 。 泊自 帝其 国， 威行专制 ，在下 者不堪 其 苦，则 民权主 义起 。 十八 世纪 之末 ， 十九 世纪之 初，专 制仆 而立 宪政体 殖焉 。 世界 开化 ，人智益 蒸，物 质发舒， 百年 锐于于栽 ，经济问题 继政治问 题之后，则 民生主义跃跃 然动，二十世 纪不得 不为 民生主义之擅 场时代 也。 是三大主义 皆基本 于 民，递 嫂变 易， 而欧 洲之 人种胥 治化焉。 ”“中 国数 千年 来都是君 主专 制政 体，这种 政体，不是 平等自由 的国 民所堪 受 的， 要去这种政体，不是专 靠 民族 革命可 以成 功…… 我们推倒满洲 政府 ，从驱 除满人那一面说是 民族 革命，从 颠覆君主政 体那一面说是政 治革 命，并 不 是把来分作 两次 去做 。 讲到那政 治革 命 的结果 ，是 建立民主立 宪政 体。 照现在这样 的政 治 论起 来，就算汉 人为 君主，也不 能不革 命。 ”摘自《孙中 山全 集 》第一卷材料 2“一 百 年以来，我们 的先 人以不屈 不挠的 斗争 反对内 外压迫 者，从 来没有停 止 过，其中 包括伟大的中国革 命先行 者孙 中山 先生所领导的 辛亥 革命在内。 我们的 先人指 示我们 ，叫 我们 完成他们 的遗 志。 我们 现在 是这样做了。 我们 团结 起来 ，以人 民解 放战 争和人民 大革命打倒 了内 外压迫者 ，宣布 中华人 民 共和国成立 了。 我们 的 民族将 从此列 入爱 好和平自由的 世界各 民族 的大家庭 ，以勇 敢 而勤劳 的姿态工 作着 ，创 造自己的 文明和幸福 ，同时 也促进 世界 的和平和自由。 我们的 民族 将再也 不是一个被人 侮辱的 民 族了 ，我 们已经 站起来 了。 ”摘自《毛泽东文集 》第五卷材料 3“辛 亥革 命推 翻了 清王朝 统治 ，结 束了统 治中国 几千 年的君 主专 制制 度，传播了 民主共 和的理念，以 巨大 的震撼力和 深刻 的影 响 力推 动了 近代中 国 社会 变革。 虽然 由于历 史进程 和社会条件的制 约，辛 亥 革命 没有改 变旧 中国半殖民 地半封建的 社会性 质，没有 改 变中国 人民的 悲惨 境遇，没有完成 实现 民族独 立、 人民解 放的历 史 任务 ，但它开 创了完 全意义上的 近代 民 族 民主 革命，极 大推动 了中华 民族 的思 想 解放 ，打 开了中国进 步潮流的 闸门 ，为中 华 民族 发展 进步探索 了道路。 ”“中 国共 产党 人是孙中 山 先生开创 的革 命事 业最坚 定的 支持 者 、最 亲密的 合作 者、最忠 实的继 承 者，不断 实现 和发展 了孙 中山 先生和辛亥 革命 先驱 的伟 大抱负。 ”摘自胡 锦涛 《在纪念辛亥革命 1 00 周年 大会上 的讲 话》(1) 如何 理解材 料1 所说的 ”就算 汉人为 君主 ，也 不能不 革命\"? (5分）(2) 为什 么说 中国共产党人 是孙 中山 开创的 革命事业 ”最忠实的 继承者\"? (5 分）",
