        "year": "2013",
        "q": "结合材料 回答问题 ：某图 书 馆向所 有读者免 费 开放 。 乞丐 、拾荒 者和衣衫 破旧 的民 工小 心翼 翼进 来了， 无人 阻拦，于 是他们 便 堂而 皇之 地在馆 内读 书 、看 报。 有读 者对此表示不 满，向馆长抱 怨说：“图书馆 是大雅之堂 ，如果允 许乞丐 和拾荒 者进入 阅 读，就 是对 其他读 者的 不尊重 。“ 馆长回答 说：“我无权拒绝他们 入内阅 读，但 你有 权选 择 离 开。 ”此事被发在 微博上，顿时触 动了 社会的神 经， 引 发人们对 人文精 神的 关 注和思考 。 中央 电视台 等主流 媒体对此进行 了报道， 一 场公 共 图书 馆 办馆 理念的大讨 论由 此引 发。公共 图书馆 一 向更 愿意向 体 面的 文化人 敞 开，常在门 口赫 然告示 ：＂ 衣冠 不整 ，谢绝入 内！ ”把读 者分 成三六九等 ，拒绝部 分人进入，其 公益性 大 打折扣 。 而该 馆馆 长希望 图书馆 ”成为每 一个读 者的 天堂 \"'\" 无论任何 人，只要进了 图书 馆，在知识面前 都享 有同 等权利， 不得有高 低贵贱之分 。 “为此， 该馆 在全 国同 行中率 先推 出免 证阅读制度 ，任何 人进 馆借 阅书 籍都不 需要 证件和费用 ，以 体现 人道 、人 文的公 共图 书馆 办馆 理念和人性化 的服 务。对于 图书馆 实行 免 费开 放可能带来 的问题，该馆 有关 负责 人感 触颇深 ：“自图书馆 实 行零 门槛后 ，我们 不仅 没有感到压力 增加 ，反而 感觉 开放 的时间 越长 ，不 尊重 这种 权利的 读 者越 少， 我们和 读 者都被 这种 和谐的 环境 所改 变。至 于进馆 要先洗 手，馆 内 并没有硬 性 规定 ， 耳濡 目染 的时间 长了，谁 都会 很自 觉 地先 洗手， 然后再 阅读 。 ”“如果 有天堂 ，天 堂应该是 图书馆 的模样。 ”这是文学大 师、曾 担任阿 根廷国立 图书 馆馆 长的博尔 赫斯的 一 句名 言。 该 图书馆向 乞丐和 拾荒者免 费 开放，不 音 一 轮明 亮的太 阳， 让乞丐和 拾荒者 在得 到温 暖的同时 ，也 净化 了我 们的心 灵。摘编自《中国青年》(2 011 年第 5 期） 、《光 明日报》( 2012年5月 10 日）(1 )从 法律角 度如 何理解 ”我无权拒绝他们 入内阅 读 ，但你有权 选择离开\"? (5分）(2 )图书 馆向乞 丐和拾 荒者免 费开放 对我们 处理人 际关 系有何启 示? (S分）",
