        "q": "结合 材料回答问题 ：材料 119 78 年我 国做出 改革 开放的 战略 决策时， 美国 《时 代》 杂志曾 质 疑说 ： “他们 的 目 标几乎不可能 按期 实现，甚 至不 可能 实现。 “经过三 十 多年 的 改革开 放，我 国国内 生 产总 值、外贸进出 口总额均 已达 到世 界 第二 位， 经济总量 占 世界 经济的 份额 提升 到 10% 左右，对 世界 经济 增长的贡献率 年 均超 过 20 % 。 据世界 银行 统计 ，我国 已经 进入中 高收 入国 家 行列 。在物质文 化生活 得到 提高之 后， 人民群众 对 未来期待更 高。 过去施 工建 厂 ，首 先考虑 的是经济 利益， 今天 引 进项 目 ，担 心 的却 是环境 污染 ； 过去期 盼吃饱 穿暖 ，今 天却 追求 吃得健康、安全； 过去梦想 有 车 有 房， 现在则 忧 虑 PM2 . 5 排放 。 城乡居 民收 入整体都有 提高 ，但 城乡 区域 发展 差距 和 居民 收入分配差距 依然 较大 ，近 10 年来 中国 基尼系 数始终处于 0. 4 以上， 超出 国际 公认“警戒线 ” ……这 个经济飞速 发展 、财 富 不断 积累 的世 界第 二大 经济体 ，在创 造着 “中国 式奇迹”的同 时， 仍有 一 些 ”中国 式 难题 “亟待 破解 。“改革 开放是我 们 党的历 史上 一 次伟 大觉 醒， 正是这个伟 大觉醒 孕育 了新时 期从 理论到 实践的伟 大 创造 。 “习近 平在 党的 十八大 之后 首 次到 地方调研就选 择了 广东 ，并向深 圳莲 花山顶 的邓小 平铜 像敬 献了 花 篮。 习近 平表示 ，之 所以到广 东来 ，就 是要到 在我 国 改革 开放 中得风气 之先的地 方 ，现 场 回顾我 国 改革 开放 的历 史进 程， 将改革开 放继 续推向 前 进。 我们 来瞻仰邓 小平铜像 ， 就是要 表明 我们将 坚定不 移推进 改革 开放， 奋力 推进 改革 开放 和现代化 建设取得 新进 展、实现 新突 破、 迈上新 台阶 。摘编 自《 人民 日报 》 (2013 年 3 月 22 日入 新华 网 (2012 年 12 月 1 1 日） 等材料 219 92 年，邓小 平同志 在南方 谈话 中说： “不坚 持社会 主义 ，不改 革开 放， 不发 展 经济 ，不改 善人民生活 ，只 能是死路 一 条。 “ 回过头来 看 ，我们对 邓小平同 志这 番话 就有更深 的理解 了。 所以，我们讲 ，只 有社会主 义才 能 救中国， 只有改 革开 放才 能发 展中 国、 发 展社 会主 义、发 展 马克思主义。正是从 历 史经 验和 现实需 要的 高度 ，党的十 八 大以来， 中央 反复 强调 ，改 革开 放是决定 当代中国 命运的 关键 一 招， 也是决定实现 ”两个 一 百年 ”奋斗 目标 、实 现中华民 族伟 大复 兴的关 键一招，实 践发展永无止境 ，解 放思 想永无止境 ，改 革开 放也永无止 境 ，停顿 和倒 退没 有出 路，改 革 开放 只有 进行时、没 有完成 时 。摘自习 近平《 关于（ 中共中 央关 于全 面深化改革若 干重大问题的决 定〉 的说明 》(1) 如何 看待 改革开放 进程 中的 ”中国式 奇迹 ”与 “中国 式难 题\"? ( 4分 ）(2)运 用 社会基本矛盾原理分析为 什么 “改革开放只有 进 行时、没 有完成时 \"? (6 分）",
