        "year": "2015",
        "q": "结合材料回 答问题：让大猫小猫都有路走计划 经济时期 全靠国家管 理市场，市场边 角被 忽略 ，很多小商品没人 去生产 ，有些 新的市场需求 也没人去注 意。 非 公有制 经济的特 点是只要市场有 需求，它就 会去满足 。 要保证各种 所有制经 济依法平 等使用生产要素， 公 平参 与市场竞 争，同等受 到法 律保护， 就需 要重 视中小企 业融资难 的问题。 经济学家成思危讲过这 样一则寓 言： 著 名科 学家牛 顿养 了两只 猫， 一 只大猫， 一 只小猫，他在 墙上 开了两 个洞， 一 个大 洞， 一 个小洞 。 有人 笑话他说 ，你 还是大科 学家呢，开 一 个洞就够了 ，小猫也 可以走大洞 嘛。 牛顿 说不对 ，如果两 个猫同 时要出 去，那大 洞肯 定被 大猫 占住了，小猫 就无 路可走。 要真正解 决小微企业的问题，就要建立真 正为小微企 业服 务的小型 银行，让大银行服务大 企业，小银行服 务小企业。 因为从商业 角度 说，大 银行本身 就嫌贫爱 富、嫌 小爱大。 小微企业市场风 险很大，交 易 成本也高。 跟大 企业签 一 个 1 亿元的合同，相 当于 跟小企业签20 个 50 0 万元 的合同。 现在居民和企业手中有大 量存款， 而小 微企业却 贷不 到款，这就 需要有一条通道，这条通道就是社 区银 行等 中小银行。 发展民营的、小型的金 融机构有 利于 解决好小 微企业的融 资困 难。 大企业是我国经济的脊梁，小微企业是血肉。 没有大企业，国民经济站不起来，但小微企业垮 了，那国民经济不就成了骨 头架 子吗？ 十八 届三 中全会 以 来，国务院陆续 出台了 关于大力扶持 小微企业健 康 发展的多项政 策，国务院 常 务会 议也多 次强调要 加 快发展民 营银 行等中小金 融机构 ，为小微企业减 负添 力。 2014 年 11 月， 李克 强总理在浙江考 察时再 次对民 营银行长 期 致力于服务 小微企业给 予了 充分 肯定 。 为小微企业打开直 接融 资大 门， 是开创 性的制 度安排。 一 大批有 巨大市场潜力的小微企业将会 成长 为支撑 中国经济转型升级 的参 天大树 。摘编 自 光明网 (2013 年 11 月 15日入 新华网 (2014 年 11 月 21日）{ 1) 现阶 段我 国发展社会主义 市场经济 为什么 应坚持 ”让大猫小猫 都有路走\"? { 6分 ）{ 2)如 何更好 地发挥非 公有制经济 在经 济发展 中的 作用 ? ( 4 分）",
