        "q": "结合材料回答问题 ：201 8年 9月 30日 ，在我 国笫 五 个烈 士纪念 日到 来之时，党和国 家领导 人同各 界代 表向 天安门广 场人民英 雄纪念碑敬 献花篮， 表达着 1 3 亿多 人民 对英 烈的深切缅 怀和崇 高敬 意。人民英雄 纪念碑基座上 镶嵌 的 8幅 革命 历 史浮雕 ，镌刻了 从虎 门销 烟到 解放战 争时期 为争取民 族独 立和人民 幸福而牺牲 的人民 英雄 。 这一 纪念 中国革 命胜 利的全景 图， 凝聚了无 数先烈的铁 骨精魂，更象 征着中国人民不忘 历 史、石氐疡奋 进的民 族精神。欲知 大道 ，必先为 史。 习近平总书记 指出产 历 史是一 面镜子。 以史 为 鉴， 才能 避免 重蹈覆辙。 对历 史，我们要 心 怀敬畏 、心 怀良 知。 历 史无法改 变， 但未 来可以塑 造。”“天地英雄 气，于 秋 尚凛 然。” 一 个 有希 望的 民族不能没有英雄 ，一 个有前 途的国家不能 没有先锋。 英雄烈 士的事迹和精神 是中华民族 共 同的 历 史记忆和 宝贵 的精神 财 富。一 段时间以 来，历 史虚无 主义思潮沉 渣泛起 。 社会上质疑英雄 烈士 、歪曲 历 史的现 象和行为不 时出 现，造成了极其恶劣 的社 会影 响，引 起了社会舆论 的 高度关注 。在社 会 各界不断的呼声 中，201 8年 4月 2 7日 ，十 三届 全国人大 常委 会第二 次会议全 票表决通 过了《中华人 民共 和国 英雄烈 士保护 法》，英雄烈士 的姓名 、肖 像、名 誉、荣 誉受 法律保护 ，禁止歪 曲、 丑化、亵渎 、否定 英雄烈 士的事迹 和精 神，宣 扬、 美化侵 略 战争 和侵略 行为 将被依 法 惩 处直至追究刑 责。英雄烈 士保护 法生效 一 个月后， 最 高人 民法 院、 最 高人民 检 察院相 继 下发 通知要 求依 法 惩处侵 害英 雄烈 士权益 、形 象等违法 行为 ；文化和 旅游部 布署查 处抹黑 英雄 烈士 等违法违 规经营行为 ；各主要 互联网 文化单 位纷 纷采 取措施 清理违规信 息、 视频 和账号； 多 地检察 机关针 对侵 害英雄烈 士名誉 等 问题 依 法启 动 诉讼 程序 。“昨天 你用 生命捍 卫我 们，今 天我们用 法律保护 你。“网 友真挚的 话 语道 出了 人们对英 雄烈士的 敬意 和爱戴 。从设立烈 士纪 念日“立大德 于社会”，到缅 怀英雄烈士仪式“扬大义 于国 家”，再到制 定英 雄烈士 保护 法”布大 信于天 下”，一 系列 致敬英烈 、崇 尚英 雄的国家 行动， 筑起了 民族复兴征程 的 闪亮灯 塔。摘编 自（ 光明 日 报》(2018 年4 月6 日） ，《人 民 日报》(2018 年6月 13 日、10 月1 日等 ）(1)如何理解“英雄烈 士的 事迹和精 神是 中华 民族共 同的 记忆 和宝贵 的精神 财富\" ? (5分）(2)从 法律社 会作用的 角 度，分析为 什么要用法律的名 义保护英雄 烈士 ? (5 分）",
