        "chap": "毛中特",
        "year": "2020",
        "q": "结合材料回答问题;材料1建设社会主义现代化国家、实现中华民，族伟大 复 兴，是 我们党孜孜 以求的宏伟目标。 自 成立以来，我们党就团结带领人民为此进行了不懈奋斗。随着改革开放逐步深化，我们党对制度建设的认识越来越深入。1980 年，邓小平同志在总结\"文化大 革命\"的教训时就指出∶\"领导制度、组织制度问题更带有根本性、全局性、稳定性和长期性。\"\"制度好可以使坏人无法任意横行，制度不好可以使好人无法充分做好事，甚至会走向反面。\"1992 年，邓小平同志在南方谈话中说∶\"恐怕再有三十年的时间，我们才会在各方面形成一整套更加成熟、更加定型的制度。\"党的十四大提出;\"到建党一百周年的时候，我们将在各方面形成一整套更加成熟更加定型的制度。\"党的十五大、十六大、十七大都对制度建设提出明确要求。50 —党的十八大以来，我们党把制度建设摆到更加突出的位置，强调\"构建系统完备、科学规范、运行有效的制度体系，使各方面制度更加成熟更加定型\"。 党的十八届三中全会首次提出\"推进国家治理体系和治理能力现代化\"这个重大命题，并把\"完善和发展 中国特色，社会主 义 制度，推进国家治理体系和治理能力现代化\"确定为全面深化改革的总目标。党的十八届五中全会进一步强调，\"十三五\"时期要实现\"各方面制度更加成熟更加定型，国家治理体系和治理能力现代化取得重大进展，各领域基础性制度体 系基本形成\"。党的十九大作出到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国的战略安排……党的十九届二中、三中全会分别就修改宪法和深化党和国家机构改革作出部署，在制度建设和治理能力建设上迈出 了新的重大步伐。党的十九届三中全会指出∶\"必须加快推进国家治理体系和治理能力现代化，努力形成更加成熟更加定型的中国特色社会主义制度。\"摘自习近平《关于〈中共中央关于坚持和完善中国特色社会主义制度推进国家治理体系和治理能力现代化若干重大问题的决定〉的说明》材料2中国特色社会主义制度是党和人民在长期实践探索中形成的科学制度体系，我国国家治理一切工作和活动都依照中国特色社会主义制度展开，我国国家治理体系和治理能力是中国特色社会主义制度及其执行能力的集中体现。实践证明，中国特色社会主义制度和国家治理体系是具有强大生命力和巨大优越性的制度和治理体系，是能够持续推动拥有近十四亿人 口大国进步和发展、确保拥有五千多年文 明史的中华民族实现\"两个一百年\"奋斗目标进而实现伟大复兴的制度和治理体系。坚持和完善中国特色，社会主义制度.推进我国国家治理体系与治理能力现代化的总目标是，到我们党成立一百年时，在各方面制度更加成熟更加定型上取得明显成效;到 2035 年，各方面制度更加完善，基本实现国家治理水平和治理能力现代化，使中国特色社会主义制度更加巩固、优越性充分体现。推进全面深化改革，既要保持中国特色社会主义制度与我国国家治理体系的稳定性和延续性，又要抓紧制定国家治理体系与治理能力现代化急需的制度，满足人民对美好生活新期待必备的制度，推动中国特色社会主义制度不断 自我完善和发展，永葆生机和活力。摘自《中共中央坚持和完善中国特色社会主义制度推进我国国家治理体系与治理能力现代化若干重大问题的决定》（1）如何理解\"中国特色社会主义制度是党和人民在长期实 践探索中形成的科学制度体系\"?（6分）（2）阐述坚持和完善中国特色社会主义制度与推进我国国家治理体系与治理能力现代化之间的关系。（4 分）",
        "opts": [],
        "ans": null,
        "explain": ""
