        "chap": "思修",
        "year": "2020",
        "q": "结合材料回答问题;2019 年 9 月 29 日，中华人民共和国国家勋章和国家荣誉称号颁授仪式在人民，大会堂降重举行。95 岁的老英雄张富清是受表彰者之一。张富清是原西北野战军战士，在解放战争的枪林弹雨中，九死一生，先后荣立特等功一次，一等功三次，二等功一次，\"战斗英雄\"称号两次。1955 年，他退役转业，主动选择到湖北省最偏远的来风县工作，先后任城关粮油所主任，三胡区副区长，区长，建行来风支行副行长等职务，直至在此岗位上离休。对工作，他脚踏实地，担当奉献，想群众之所想，急群众之所急，他推动水电站建设，让山村进入\"电力时代\";他牵头办起桐油和茶叶基地，牧场，群众生活明显改善;他与群众一起，找水源修道路，解决群众出行难，吃水难的 问题……·对待战功荣誉，他刻意隐瞒，连自己的儿女都不知情。如果不是 2018 年一次退役军人的信息采集，他的事迹可能依旧无人知晓。很多人不禁好奇，张富清为何一辈子深藏功名?为何在平凡岗位上如此低调奉献却甘之如饴?他在回答记者提问时说∶\"和我并肩作战的战友，献出了自己宝贵的生命，和牺牲的战友相比，我有什么资格张扬呢?我和战友们跟着党奋斗的目标是为了建立新中国，就是为了人民能走上幸福美满的道路，这一切都是我应 该做的。\"— 52 —正是有这样的信念，他在每一次的战斗中都要担任\"突击队员\";正是有这样的信念，他放弃留在大城市。他的岗位、身份一再改变，始终不变的，是他的赤子之心。新中国 70 年的不凡岁月中，闪耀着一个个光辉的名字，一段段感人的故事。他们不懈奋斗的精神和忠诚、执着、朴实的鲜明品格，是亿万中华儿女的榜样，激励我们在追梦之路上砥砺前行。摘自《人民日报》（2019年5月 27日、9月 24 日、9月 30 日）《光明日报》（2019年 8 月 10日）（1）结合张富清高尚的人生追求，说明理想信念的力量。（6 分）（2）国家颁授国家勋章 和国家荣誉称号对全社会弘扬和践行社会核心价值观有何重要意义?（4分）",
        "opts": [],
