        "conf": "real",
        "chap": "时政",
        "year": "2020",
        "q": "结合材料回答问题∶材料.12018 年 11 月5 日，首届中国国际进口博览会（简称进博会）在上海开幕。这是世界上第一个以进口为主题的国家级展会，是国际贸易发展史上一大创举.体现了中国推动发展自由贸易的一贯立场，是中国支持经济全球化的实际行动。共有 172 个国家、地区和国际组织参会，3600多家企业参展，展览总面积达 30 万平方米，超过 40 万名境内外采购商到会洽谈采购。在开幕式上，中国国家主席习近平发表了题为《共建创新包容的开放型世界经济》的主旨演讲，明确表示;\"中国国际进口博览会由中国主 办，世界贸易组织等多个国际组织和众 多 国家共同参与，不是中国的独唱，而是各国的大合唱…·不仅要年年办下去，而且要办出水平，办出成效、越办越好。\"习近平阐述了\"经济全球化是不可逆转的历史大势\"观点;提出了各国应该\"坚持开放通融、拓展互利合作空间，坚持创新引领、加快新旧动能转换，坚持包容普惠，推动各国共同发展\"的主张;宣布了中国在推进\"激发进口潜力，持续放宽市场准入、营造国际一流营商环境、打造对外开放新高地、推动多边和双边合作深入发展\"方面的措施。摘编自新华网（2018 年 11月 5日）材料 22019 年 11 月 5 日到 10日，第二届中国国际进口博览会在上海如期举行，共有 181 个国家、地区、国际组织与会，3800 多家企业参展，注册报名的专业采购商和观众达 50 万，展览面积 33 万平方米，涵盖装备、贸易、汽车、科技生活、品质生活、医疗器械及医药保健、服务等五大板块、七个展区;不少世界 500 强和行业龙头企业的高管亲自带队参展。首发的新产品、新技术超过首届。值得一提的是，美国企业参展数量达 192 家，参展面积达 4.75 万平方米，为所有参展国之首。习近平在开幕式上发表的题为《开放合作 命运与共》的主旨演讲中指出，首届进博会上宣布的中国扩大对外开放的 5 方面举措已经基本落实，同有关国家达成的 98 项合作事项中，23项 已经办结，47 项正在积极推进，28 项也在跟进推进。习近平明确表示;站在新的历史起点，中国开放的大 门只会越开越大，中国将继续扩大市场开放、继续完善开放格局，继续优化营商环境，继续深化多 双边合作，继续推进\"一带一路\"。习近平在欢迎与会各国贵宾时发表的致辞中进一步指出∶\"中国国际进口博览会交易的是商品和服务，交流的是文化和理念。\"摘自新华网（2019年 11月 5日）（1）阐述中国举办国际进口博览会的背景和意义。（5分）（2）为什么说进博会\"交易的是商品和服务，交流的是文化和理念\"?（5 分）— 53 —",
        "opts": [],
        "ans": null,
