        "q": "2020年颁布的《中华人民共和国民法典》是新中国第一部以法典命名的法律。这部法典共 7编1260条，包括总则、物权、合同、人格权、婚姻家庭、继承、侵权责任以及附则，被称为“社会生活的百科全书”。它系统地整合了新中国成立 70多年来司法实践中形成的民事法律规范,汲取和借鉴了中外优秀法治文明建设的有益成果，是一部具有鲜明中国特色、实践特色、时代特色的民法典，开创了我国法典编纂立法的先河。编纂民法典的重大意义是",
