        "conf": "real",
        "chap": "马原",
        "year": "2021",
        "q": "结合材料回答问题：当今世界正经历百年未有之大变局，不稳定性不确定性明显增强。当前和今后一个时期，我国发展仍然处于重要战略机遇期，但机遇和挑战都有新的发展变化。面对严峻复杂的形势，我国要赢得优势、赢得主动、赢得未来，就必须准确识变、科学应变、主动求变，善于从眼前的危机、眼前的困难中捕捉和创造机遇。我国已进入高质量发展阶段，发展具有多方面优势和条件，同时发展不平衡不充分问题仍然突出，重点领域关键环节改革任务仍然艰巨，创新能力不适应高质量发展要求，农业基础还不稳固，城乡区域发展和收入分配差距较大，生态环保任重道远，民生保障存在短板，社会治理还有弱项。“智者虑事，虽处利地，必思所以害；虽处害地，必思所以利”。习近平总书记指出：“从哲学意义上讲，'难'是在任何领域前进道路上永恒的命题。”人类历史一再表明，顺境中存危机，逆境中有机遇。新冠肺炎疫情给我国经济社会发展带来前所未有的挑战，一些传统产业受到严重影响，同时也催生出一些新型经济业态，如“指尖交易” “云端销售” “宅经济”等，给我国加快科技发展、推动产业优化升级带来新机遇。作为矛盾的双方，危和机在一定条件下可以相互转化，关键是要主动求变，充分发挥主观能动性，认清“危”中之需、找准发展之“机”，积极创造条件，做到因势利导，打好化危为机的战略主动仗。变局因其复杂多变而充满不确定性。“要坚持用全面、辩证、长远的眼光分析当前形势，努力在危机中育新机、于变局中开新局”。只有准确把握分析我国发展阶段、环境、条件变化，看清变局本质和发展大势，顺势而为、谋事而动，提升危中寻机、化危为机的能力，沉稳应对变局、开拓新局，集中力量办好自己的事，推动形成新发展格局，才能牢牢把握化危为机的主动权，为不确定的世界增加确定性。摘编自《人民日报》（2020年 4 月 3 日、4月 16日、9 月 25日）（1）分析“在危机中育新机、于变局中开新局”这一论断所蕴含的唯物辩证法原理。（5 分）（2）运用主观能动性与客观规律性相统一的原理，说明“主动求变”与“准确识变”之间的关系。（5 分）",
        "opts": [],
