        "type": "sa",
        "tier": "基础",
        "conf": "real",
        "chap": "毛中特",
        "year": "2021",
        "q": "结合材料回答问题：- 7 -材料 11979年 12月 6日，邓小平同志在会见日本首相大平正芳时谈到了二十世纪末我国的奋斗目标：“我们要实现的四个现代化，是中国式的四个现代化。我们的四个现代化的概念，不是像你们那样的现代化的概念，而是'小康之家'。”从此，“小康”成为我国经济社会发展战略中的重要概念。党的十三大确立了从“解决人民的温饱问题”，到二十世纪末“人民生活达到小康水平”，再到二十一世纪中叶“人民生活比较富裕，基本实现现代化”的战略目标。党的十五大提出到二 O — O 年、建党一百年和新中国成立一百年的发展目标，要求在新世纪头十年使人民的小康生活更加宽裕。党的十六大进一步提出要在本世纪头二十年全面建设惠及十几亿人口的更高水平的小康社会。党的十八大提出到二 O 二 O 年实现全面建成小康社会奋斗目标。党的十九大进一步明确了决胜全面建成小康社会的战略安排，提出从二 O 二 O 年到本世纪中叶，在全面建成小康社会的基础上，分两步走全面建成社会主义现代化强国。党的十九届五中全会通过的《中共中央关于制定国民经济和社会发展第十四个五年规划和二 O三五年远景目标的建议》宣告：“‘十三五’规划目标任务即将完成，全面建成小康社会胜利在望，中华民族伟大复兴向前迈出了新的一大步，社会主义中国以更加雄伟的身姿屹立于世界东方。”摘编自《人民日报》（2020年 7月 15日、11月 4日）材料 2“人民对美好生活的向往，就是我们的奋斗目标。”新中国成立后特别是改革开放以来，中国共产党人秉持为中国人民谋幸福、为中华民族谋复兴的初心和使命，始终与人民想在一起、干在一起。党的十八大以来，以习近平同志为核心的党中央顺应我国经济社会发展和广大人民群众新期待，提出了全面建成小康社会新的目标要求，赋予了 “小康”更高的标准、更丰富的内涵。为决胜全面建成小康社会，党领导人民聚焦短板弱项，攻坚克难，砥砺前行，经济社会实现了跨越式发展。2019年，我国国内生产总值达到 99. 0865万亿元，预计 2020年突破 100万亿元，稳居世界第二；居民恩格尔系数下降到 28. 2% ,居民消费结构加快从生存型向发展型进而向享受型转变；脱贫攻坚成果举世瞩目，现行标准下农村贫困人口全部脱贫；建成了世界上规模最大的社会保障体系，基本医疗保险覆盖超过 13亿人，基本养老保险覆盖近 10亿人。14亿中国人民即将普遍过上殷实宽裕的生活。这无疑是中华民族发展史上亘古未有的伟大跨越。全面建成小康社会不是终点，而是新生活、新奋斗的起点。我们既要为全面建成小康社会跑好“最后一公里”，又要乘势而上开启全面建设社会主义现代化国家新征程，实现“两个一百年”奋斗目标有机衔接。这是恢弘壮丽的新征程，又是任重道远的新征程！摘编自《人民日报》（2020年 6月 30日、7 月 20日）(1)从人民生活水平不断提高的视角，分析我国从“解决温饱”到“达到小康水平”，再到“全面建成小康社会”所体现的中国特色社会主义制度优势。（6 分）(2)如何理解“全面建成小康社会不是终点，而是新生活、新奋斗的起点”？（4 分）- 8 -",
