        "chap": "思修",
        "year": "2021",
        "q": "结合材料回答问题：新冠肺炎疫情是百年来全球发生的最严重的传染病大流行，是新中国成立以来我国遭遇的传播速度最快、感染范围最广、防控难度最大的重大突发公共卫生事件。面对严重疫情，中国共产党团结带领全国各族人民，进行了一场惊心动魄的抗疫大战，经过艰苦卓绝的斗争，付出巨大努力，取得抗击疫情斗争重大战略成果。武汉和湖北成为这次疫情防控战的主战场。面对疫情考验，党中央一声令下，从抗疫最前线到防疫大后方，从“天涯海角”到“漠河北极”，从雪域高原到黄浦江畔，全国人民并肩实施了规模空前的生命大救援，用 10多天时间先后建成火神山医院和雷神山医院、改建 16座方舱医院、开辟 600多个集中隔离点，19个省区市对口帮扶除武汉以外的 16个市州，在最短时间内解决了医疗资源和物资供应的短缺性难题。面对生死考验，平日里默默无闻的工人、农民、医生等挺身而出，用血肉- 9 -之躯挺起国家的脊梁。“天使白” “橄榄绿”“守护蓝”“志愿红”迅速集结。习近平总书记在全国抗击新冠肺炎疫情表彰大会上深情地说：“全国人民都'为热干面加油’”。抗击疫情犹如大考，考出了令人赞叹的中国精神、中国力量、中国担当，考出了家的团结、国的凝聚、每个人的责任。他们当中，有满头银发乘火车赶赴武汉的钟南山院士，有因操劳过度“把胆留在武汉”的张伯礼院士，有身患渐冻症仍蹒跚急行的张定宇院长，有为研制疫苗以身试验的陈薇院士等。他们当中，有牺牲在湖北疫情防控一线的白衣战士刘智明、基层民警吴涌、社区干部廖建军，有每天送医护人员上下班的爱心人士等。参加抗疫的医务人员中有近一半是“90后” “00后”，他们有一句话感动了中国：“2003年非典的时候你们保护了我们，今天轮到我们来保护你们了”。人无精神则不立，国无精神则不强。唯有精神上站得住、站得稳，一个民族才能在历史洪流中屹立不倒。“在这场同严重疫情的殊死较量中，中国人民和中华民族以敢于斗争、敢于胜利的大无畏气概，铸就了生命至上、举国同心、舍生忘死、尊重科学、命运与共的伟大抗疫精神。”伟大抗疫精神是中国精神的生动诠释，必将激励新时代中华儿女以更加担当有为的姿态为全面建设社会主义现代化国家、实现中华民族伟大复兴注入强大的力量。摘编自《光明日报》（2020年 9月 9日）、新华网（2020年 9月 17日）、《人民日报》（2020年 9 月 18日）（1）伟大抗疫精神是中国精神的生动诠释，“全国人民都为'热干面加油’”彰显了什么样的中国精神？（6 分）（2）伟大抗疫精神激励新时代青年如何担当民族复兴的时代使命？（4 分）",
