        "q": "结合材料回答问题：材料 1当今世界进入大动荡大变革时期。特朗普政府崇尚权力政治，提出“美国第一”，以“经济民族主义”对抗“全球主义”，以单边主义取代多边主义。自 2017年 1月 23日以来，美国相继宣布退出《跨太平洋伙伴关系协定》、气候变化《巴黎协定》、联合国教科文组织、《全球移民协议》、《伊朗核问题全面协议》、联合国人权理事会、万国邮政联盟、《武器贸易条约》、《中导条约》、《开放天空条约》等重要国际组织和国际机制。面对新冠肺炎疫情全球大流行局面，特朗普政府不仅没有积极参与全球卫生治理，反而正式通知联合国将于 2021年 7 月退出世界卫生组织。摘编自新华网（2020年 9月 20日至 25日）材料 2中国加入了几乎所有政府间国际组织和 500多项国际公约，忠实履行国际义务，严格恪守国际承诺。习近平主席在联合国成立 70周年系列峰会上宣布的支持联合国事业的一系列重大倡议和举措，目前均已得到落实。中国 8000人规模维和待命部队和 300 人规模常备维和警队在联合国完成注册。中国一联合国和平与发展基金开展了 80多个项目，使用资金规模 6770万美元，为联合国维和、反恐、能源、农业、基建、卫生、教育等领域工作提供支持。南南合作援助基金在 30多个发展中国家实施 80余个项目。中国向联合国妇女署捐款 1000万美元。面对新冠肺炎疫情，中国向世界卫- 10 -生组织提供 5000万美元现汇援助；向 150多个国家和国际组织提供物资援助；承诺两年内提供 20亿美元国际援助、中国新冠疫苗研发完成并投入使用后将作为全球公共产品……摘编自新华网（2020年 9 月 10日）材料 3纪念联合国成立 75周年峰会于 2020年 9月 21日举行。这是在特殊历史节点举行的具有特殊意义的联合国大会。联合国秘书长古特雷斯在发表讲话时表示，当今国际社会面临过多的多边挑战,但缺乏多边的解决方案，需要具有远见、雄心、影响力的更高效的多边主义。习近平主席在发言中指出，联合国的 75年，是多边主义快速发展的 75年。突如其来的新冠肺炎疫情对全世界是一次严峻考验。我们必须严肃思考：世界需要一个什么样的联合国？在后疫情时代，联合国应该如何发挥作用？为此，习近平提出四点建议，即主持公道、厉行法治、促进合作、聚焦行动；重申中国将始终做多边主义的践行者，积极参与全球治理体系改革和建设。古特雷斯评价道，“中国是联合国事业的坚定支持者和主要参与者，也是国际合作和多边主义的支柱，发挥着核心作用。”摘编自新华网（2020年 9 月 22日）（1）分析中美两国政府对待国际组织和国际事务态度的差异，并指出这种差异的实质。（5 分）（2）习近平主席所提“四点建议”对于后疫情时代全球治理体系改革和建设有何意义？（5 分）",
