        "chap": "毛中特",
        "year": "2022",
        "q": "结合材料回答问题在中国共产党成立100周年的重要历史时刻，在党和人民胜利实现第一个百年奋斗目标、全面建成小康社会，正在向着全面建成社会主义现代化强国的第二个百年奋斗目标迈进的重大历史关头，党的十九届六中全会于2021年11月8日至11日在北京胜利举行，审议通过了《中共中央关于党的百年奋斗重大成就和历史经验的决议》。全会聚焦总结党的百年奋斗重大成就和历史经验，深入研究我们党不断推进马克思主义中国化的百年历程，把“坚持理论创新”概括为党百年奋斗的十条历史经验之一，深刻指出党的百年奋斗展示了马克思主义的强大生命力。“我们党的历史，就是一部不断推进马克思主义中国化的历史，就是一部不断推进理论创新、进行理论创造的历史”一百年来，中国共产党人“顶马克思主义的“天”，“立”中国国情的“地”，在马克思主义及其中国化创新理论的指引下，团结带领中国人民，书写了中华民族几千年历史上最恢宏的史诗。实践充分证明，党之所以能够领导人民在一次次求索、一次次挫折、一次次开拓中完成中国其他各种政治力量不可能完成的艰巨任务，根本在于坚持解放思想、实事求是、与时俱进、求真务实，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持实践是检验真理的唯一标准，坚持一切从实际出发，及时回答时代之间、人民之间，不断推进马克思主义中国化时代化，用马克思主义中国化的科学理论引领伟大实践。中国特色社会主义进入新时代，中国共产党面临的主要任务是，实现第一个百年奋斗目标，开启实现第二个百年奋斗目标新征程，朝着实现中华民族伟大复兴的宏伟目标继续前进。在这个风云激荡、波澜壮阔的新时代，世情国情党情持续发生深刻复杂变化，向中国共产党人提出系列新的重大课题。《决议》突出中国特色社会主义新时代这个重点，在党的十九大报告“八个明确”的基础上，用“十个明确”对习近平新时代中国特色社会主义思想的核心内容作了进一步概括和阐述。《决议》还从13个方面分领域总结新时代党领导人民取得的巨大成就，井重点概括了其中的原创性的理念和思想，这些战略思想和创新理念，是党对中国特色社会主义建设规律认识深化和理论创新的重大成果。《决议》指出，习近平新时代中国特色社会主义思想实现了马克思主义中国化新的飞跃。“党确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位，反映了全党全军全国各族人民共同心愿，对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。”摘编自《求是》（2021年第22期）、《人民日报》（2021年11月16日）（1）怎样认识我们党的历史“就是一部不断推进理论创新、进行理论创造的历史”？（5分）为了实现中华民族伟大复兴，中国共产党团结带领中国人民，自信自强、守正创新，统揽伟大斗争、伟大工程、伟大事业、伟大梦想，创造了新时代中国特色社会主义的伟大成就（1分），实现第一个百年奋斗目标，明确实现第二个百年奋斗目标的战略安排，党和国家事业取得历史性成就、发生历史性变革，为实现中华民族伟大复兴提供了更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量（1分）。总结党的百年奋斗重大成就和历史经验，是在建党百年历史条件下开启全面建设社会主义现代化国家新征程、在新时代坚持和发展中国特色社会主义的需要（1分）；是增强政治意识、大局意识、核心意识、看齐意识，坚定道路自信、理论自信、制度自信、文化自信，做到坚决维护习近平同志党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导，确保全党步调一致向前进的需要（1分）；是推进党的自我革命、提高全党斗争本领和应对风险挑战能力、永葆党的生机活力、团结带领全国各族人民为实现中华民族伟大复兴的中国梦而继续奋斗的需要（1分）。（2）结合中华民族伟大复兴战略全局和世界百年未有之大变局，闸述如何理解习近平新时代中国特色社会主义思想“实现了马克思主义中国化新的飞跃”。（5分）当前，新冠肺炎疫情仍在全球蔓延，世界经济复苏面临不确定性，国际热点问题延宕难解，气候变化等非传统安全挑战层出不穷。要解决人类面临的全球性问题，必须让多边主义的火炬照亮人类前行之路，团结起来开展全球行动、全球应对、全球合作。（1分）十八大以来，中国特色社会主义进入了新时代，中华民族面临着从站起来、富起来向强起来跨越的历史任务，中国共产党人进一步把马克思主义与中国实际相结合，实现了马克思主义中国化的新飞跃，形成了习近平新时代中国特色社会主义思想。（1分）习近平新时代中国特色社会主义思想就新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党等重大时代课题，提出一系列原创性的治国理政新理念新思想新战略。（2分）习近平新时代中国特色社会主义思想是当代中国马克思主义、21世纪马克思主义，是中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃。（1分）",
        "opts": [],
        "ans": null,
        "explain": ""
