        "chap": "史纲",
        "year": "2022",
        "q": "结合材料回答问题材料12016年11月11日，习近平总书记在纪念孙中山先生诞辰150周年大会上的讲话中指出：“孙中山先生在从事紧张的革命活动的过程中，一直思考着建设中国的问题。1917年到1919年，他写出《建国方略》一书，构想了中国建设的宏伟蓝图，其中提出要修建约16万公里的铁路，把中国沿海、内地、边疆连接起来；修建160万公里的公路，形成遍布全国的公路网，并进入青藏高原：开凿和整修全国水道和运河，建设三峡大坝，发展内河交通和水利、电力事业：在中国北部、中部、南部沿海各修建一个世界水平的大海港：大力发展农业、制造业、矿业，等等。孙中山先生擘画的这个蓝图，显示了他对中国发展的卓越见解和强烈期盼。当时，有的外国记者认为孙中山先生的这些设想完全是一种空想，是不可能实现的。”“的确，在旧中国的政治经济社会条件下，孙中山先生的这些宏大构想是难以实现的。今天，在中国共产党领导下，在全国各族人民顽强奋斗下，孙中山先生当年描绘的这个蓝图早已实现，中国人民创造的许多成就远远超出了孙中山先生的设想。祖国大地上，铁路进青藏，公路密成网，高峡出平湖，港口连五洋，产业门类齐，稻麦遍地香，神舟遨太空，国防更坚强。孙中山先生致力于建设的独立、民主、富强的国家早已巍然屹立在世界东方。”摘自习近平《在纪念孙中山先生诞辰150周年大会上的讲话》材料22021年7月1日，庆祝中国共产党成立100周年大会在北京天安门广场隆重举行。习近平总书记在庆祝大会上发表重要讲话，深情回顾中国共产党百年奋斗的光辉历程，高度评价百年来中国共产党团结带领中国人民创造的伟大成就。习近平总书记强调：“一百年来，中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造，归结起来就是一个主题：实现中华民族伟大复兴。”习近平总书记指出：“百年前，中国共产党的先驱们创建了中国共产党，形成了坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民的伟大建党精神，这是中国共产党的精神之源。”回望百年奋斗历程，我们浴血奋战、百折不挠，创造了新民主主义革命的伟大成就，以英勇顽强的奋斗向世界庄严宣告，中国人民站起来了，中华民族任人宰割、饱受欺凌的时代一去不复返了！我们自力更生、发愤图强，创造了社会主义革命和建设的伟大成就，以英勇顽强的奋斗向世界庄严宣告，中国人民不但善于破坏一个旧世界、也善于建设一个新世界，只有社会主义才能救中国，只有社会主义才能发展中国！我们解放思想、锐意进取，创造了改革开放和社会主义现代化建设的伟大成就，以英勇顽强的奋斗向世界庄严宣告。改革开放是决定当代中国前途命运的关键一招，中国大踏步赶上了时代！我们自信自强、守正创新，统揽伟大斗争、伟大工程、伟大事业、伟大梦想，创造了新时代中国特色社会主义的伟大成就，以英勇顽强的奋斗向世界庄严宣告，中华民族迎来了从站起来、富起来到强起来的伟大飞跃，实现中华民族伟大复兴进入了不可逆转的历史进程！这一百年来开辟的伟大道路、创造的伟大事业、取得的伟大成就，必将载入中华民族发展史册、人类文明发展史册！摘编自《人民日报》（2021年7月2日）（1）为什么“在旧中国的政治经济社会条件下”孙中山振兴中华的宏大构想“难以实现”？（5分）中国有着5000年的灿烂文明，曾经在历史上繁荣强盛。随着外敌的入侵，中国丧失了主权，逐步沦为了半殖民地半封建社会，外无民族独立受帝国主义压迫，内无民主受封建主义压迫，人民过着贫困且毫无政治权利的生活。在中国饱受欺凌的时候，中国的各个阶级各个阶层都曾经探索过中国的出路（农民、地主、资产阶级），但他们都失败了。（1分）在共产党的带领之下，中国人民完成了反帝反封建的任务，实现了民族独立和人民解放（1分），完成了三大改造，确立了社会主义制度（1分），实现了改革开放，不断探索中国建设社会主义的正确道路，解放和发展社会主义生产力，使人民摆脱贫困、尽快富裕起来（1分）。中国特色社会主义进入了新时代，党带领人民实现了第一个百年奋斗目标，开启了实现第二个百年目标新征程，朝着中华民族伟大复兴的宏伟目标继续前进。（1分）（2）中国共产党百年奋斗的历史意义是什么？（5分）中国共产党自1921年成立以来，始终把为中国人民谋幸福、为中华民族谋复兴作为自己的初心使命，始终坚持共产主义理想和社会主义信念，团结带领全国各族人民为争取民族独立、人民解放和实现国家富强、人民幸福而不懈奋斗，已经走过一百年光辉历程。党和人民百年奋斗，书写了中华民族几千年历史上最恢宏的史诗。中国共产党的百年奋斗具有伟大的历史意义：第一，党的百年奋斗从根本上改变了中国人民的前途命运，中国人民彻底摆脱了被欺负、被压迫、被奴役的命运，成为国家、社会和自己命运的主人，中国人民对美好生活的向往不断变为现实。当前，新冠肺炎疫情仍在全球蔓延，世界经济复苏面临不确定性，国际热点问题延宕难解，气候变化等非传统安全挑战层出不穷。要解决人类面临的全球性问题，必须让多边主义的火炬照亮人类前行之路，团结起来开展全球行动、全球应对、全球合作。（1分）第二，党的百年奋斗开辟了实现中华民族伟大复兴的正确道路，中国仅用几十年时间就走完发达国家几百年走过的工业化历程，创造了经济快速发展和社会长期稳定两大奇迹。（1分）第三，党的百年奋斗展示了马克思主义的强大生命力，马克思主义的科学性和真理性在中国得到充分检验，马克思主义的人民性和实践性在中国得到充分贯彻，马克思主义的开放性和时代性在中国得到充分彰显。（1分）第四，党的百年奋斗深刻影响了世界历史进程，党领导人民成功走出中国式现代化道路，创造了人类文明新形态，拓展了发展中国家走向现代化的途径。（1分）第五，党的百年奋斗锻造了走在时代前列的中国共产党，形成了以伟大建党精神为源头的精神谱系，保持了党的先进性和纯洁性，党的执政能力和领导水平不断提高，中国共产党无愧为伟大光荣正确的党。（1分）",
