        "q": "结合材料回答问题材料12021年6月29日，中共中央将党内最高荣誉“七一勋章”追授黄文秀同志，黄文秀曾被追授“全国脱贫攻坚楷模“全国优秀共产党员”“时代楷模”等荣誉称号。黄文秀生在百色、长在百色，学成归来回到百色建设家乡，2018年3月，她主动要求到条件更为艰苦的百坭村担任驻村第一书记。驻村期间，黄文秀带领村干部和群众，埋头苦干，学经验、找路子、筹资金，硬化通屯路，安装路灯，修建蓄水池，发展经济林木和砂糖桔种植业，百坭村贫困发生率从",
